        row(T("Drugs", "Препарати"), ...shielding.map(([key, d]) => tile(key, nm(d), !!state.fx.drugs[key],
          function () { state.fx.drugs[key] = !state.fx.drugs[key]; this.setAttribute("aria-pressed", String(state.fx.drugs[key])); update(); })));
